{"content":"#!/usr/bin/env python3
"""Health probe for local service on port 42911. Prints UP/DOWN status."""
import urllib.request

URL = "http://127.0.0.1:42911/health"

try:
    req = urllib.request.Request(URL, headers={"User-Agent": "hermes-healthcheck"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        status = resp.status
        body = resp.read(500).decode("utf-8", "replace").strip()
        if 200 <= status < 300:
            print("STATUS: UP")
        else:
            print("STATUS: DOWN")
        print(f"HTTP {status}")
        if body:
            print(f"BODY: {body}")
except Exception as e:
    print("STATUS: DOWN")
    print(f"ERROR: {type(e).__name__}: {e}")
